# ZagBench – BeFannkuch (Ruby port of BeFannkuch.class.st).
#
# Fannkuch-Redux: count pancake flips across all permutations of 0..n-1.
# Permutations generated by the rotation-based algorithm (Benchmark Game
# reference) so that checksum signs alternate correctly with permutation order.

require_relative 'benchmark'

class BeFannkuch < Benchmark
  def self.main_iterations  = 2
  def self.inner_iterations = 10

  # Verification table (checksum, max_flips) for n = 1..11, indexed by n-1
  EXPECTED = [
    [0,      0],   # n=1
    [-1,     1],   # n=2
    [2,      2],   # n=3
    [4,      4],   # n=4
    [11,     7],   # n=5
    [49,     10],  # n=6
    [228,    16],  # n=7
    [1616,   22],  # n=8
    [8629,   30],  # n=9
    [73196,  38],  # n=10
    [556355, 51],  # n=11
  ].freeze

  def inner_benchmark_loop(iterations)
    _verify(_solve(iterations), iterations)
  end

  private

  def _solve(n)
    perm1    = Array.new(n) { |i| i }          # [0, 1, ..., n-1]
    count    = Array.new(n) { |r| r + 1 }      # [1, 2, ..., n]
    perm     = Array.new(n)
    checksum  = 0
    max_count = 0
    nperm     = 0

    loop do
      # Process current permutation
      if perm1[0] != 0
        n.times { |i| perm[i] = perm1[i] }
        flips = 0
        while perm[0] != 0
          k  = perm[0]
          lo = 0
          hi = k
          while lo < hi
            perm[lo], perm[hi] = perm[hi], perm[lo]
            lo += 1
            hi -= 1
          end
          flips += 1
        end
        max_count = flips if flips > max_count
      else
        flips = 0
      end

      checksum += nperm.even? ? flips : -flips
      nperm += 1

      # Advance to the next permutation via left-rotation
      r = 1
      loop do
        perm0 = perm1[0]
        r.times { |i| perm1[i] = perm1[i + 1] }
        perm1[r] = perm0
        count[r] -= 1
        if count[r] > 0
          break
        else
          count[r] = r + 1   # reset
          r += 1
          return [checksum, max_count] if r >= n
        end
      end
    end
  end

  def _verify(result, iterations)
    if iterations < 1 || iterations > 11
      puts "No verification result for #{iterations} found"
      return false
    end
    expected = EXPECTED[iterations - 1]
    result[0] == expected[0] && result[1] == expected[1]
  end
end
